INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('7ca068b56daf8a9c', 'standard-fijian', 'word', 'daru', 'daru', 'pronoun', 'we two, you and I (short form of kedaru in subject use)', '', '', '', 'Short form of kedaru in this set. It may have other uses. Durusau names its role only when it marks the subject within a matavu; a Fijian phrase remains to be checked. Attached -daru appears in nodaru; this is a different grammatical use from free daru.', '{"role":{"fijian":"isosomi","english":"shortened pronoun form in subject use here; durusau only within a matavu"},"relatedWords":["kedaru"],"comparison":"Daru is shorter than kedaru here; identify its role from the whole phrase. Attached -daru appears in nodaru; this is a different grammatical use from free daru.","furtherLink":{"label":"Explore daru in Object licensing in Fijian and the role of adjacency (2019)","href":"https://link.springer.com/article/10.1007/s11049-019-09442-1"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Short form of kedaru in this set. It may have other uses. Durusau names its role only when it marks the subject within a matavu; a Fijian phrase remains to be checked. Attached -daru appears in nodaru; this is a different grammatical use from free daru."}}', '[{"sourceId":"naisema-founder-pronouns-2026-11-01"},{"sourceId":"fijian-object-licensing-2019"},{"sourceId":"fijian-pronoun-paradigm-study"}]', '["pronouns"]', 'daru | we two, you and i (short form of kedaru in subject use) | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('8560b1d613c43e01', 'standard-fijian', 'word', 'datou', 'datou', 'pronoun', 'we few, including you and me (short form of kedatou in subject use)', '', '', '', 'Short form of kedatou in this set. It may have other uses. Durusau names its role only when it marks the subject within a matavu; a Fijian phrase remains to be checked. Attached -datou appears in nodatou and wekadatou; this is not a separate-word use.', '{"role":{"fijian":"isosomi","english":"shortened pronoun form in subject use here; durusau only within a matavu"},"relatedWords":["kedatou","tou"],"comparison":"Datou is shorter than kedatou here; identify its role from the whole phrase. Attached -datou appears in nodatou and wekadatou; this is not a separate-word use.","furtherLink":{"label":"Explore datou in Object licensing in Fijian and the role of adjacency (2019)","href":"https://link.springer.com/article/10.1007/s11049-019-09442-1"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Short form of kedatou in this set. It may have other uses. Durusau names its role only when it marks the subject within a matavu; a Fijian phrase remains to be checked. Attached -datou appears in nodatou and wekadatou; this is not a separate-word use."}}', '[{"sourceId":"naisema-founder-pronouns-2026-11-01"},{"sourceId":"fijian-object-licensing-2019"},{"sourceId":"fijian-pronoun-paradigm-study"},{"sourceId":"fijian-wekadatou-acts-15-1864"}]', '["pronouns"]', 'datou | we few, including you and me (short form of kedatou in subject use) | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('bafd340ae553d00a', 'standard-fijian', 'word', 'tou', 'tou', 'pronoun', 'we few, including you and me; shortened form in the appropriate context (short form of kedatou in subject use)', '', '', '', 'Short form of kedatou in this set. It may have other uses. Durusau names its role only when it marks the subject within a matavu; a Fijian phrase remains to be checked. Neitou has exclusive -itou, not the inclusive short form tou.', '{"role":{"fijian":"isosomi","english":"shortened pronoun form in subject use here; durusau only within a matavu"},"relatedWords":["kedatou","datou"],"comparison":"Tou is shorter than kedatou here; its other uses need their own contexts. Neitou has exclusive -itou, not the inclusive short form tou.","furtherLink":{"label":"Explore tou in Object licensing in Fijian and the role of adjacency (2019)","href":"https://link.springer.com/article/10.1007/s11049-019-09442-1"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Short form of kedatou in this set. It may have other uses. Durusau names its role only when it marks the subject within a matavu; a Fijian phrase remains to be checked. Neitou has exclusive -itou, not the inclusive short form tou."}}', '[{"sourceId":"naisema-founder-pronouns-2026-11-01"},{"sourceId":"fijian-object-licensing-2019"},{"sourceId":"fijian-pronoun-paradigm-study"}]', '["pronouns"]', 'tou | we few, including you and me; shortened form in the appropriate context (short form of kedatou in subject use) | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('d02a066d030ca728', 'standard-fijian', 'word', 'da', 'da', 'pronoun', 'we many, including you and me (short form of keda in subject use)', '', '', '', 'Short form of keda in this set. It may have other uses. Durusau names its role only when it marks the subject within a matavu; a Fijian phrase remains to be checked. Attached -da appears in noda; this is a different use from free da.', '{"role":{"fijian":"isosomi","english":"shortened pronoun form in subject use here; durusau only within a matavu"},"relatedWords":["keda"],"comparison":"Da is shorter than keda here; other uses of da need separate senses. Attached -da appears in noda; this is a different use from free da.","furtherLink":{"label":"Explore da in Object licensing in Fijian and the role of adjacency (2019)","href":"https://link.springer.com/article/10.1007/s11049-019-09442-1"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Short form of keda in this set. It may have other uses. Durusau names its role only when it marks the subject within a matavu; a Fijian phrase remains to be checked. Attached -da appears in noda; this is a different use from free da."}}', '[{"sourceId":"naisema-founder-pronouns-2026-11-01"},{"sourceId":"fijian-object-licensing-2019"},{"sourceId":"fijian-pronoun-paradigm-study"}]', '["pronouns"]', 'da | we many, including you and me (short form of keda in subject use) | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('0dbe048685bfa4b1', 'standard-fijian', 'word', 'au', 'au', 'pronoun', 'me (object use)', '', '', '', 'Founder-supplied object use of an isosomi form. Matanauni sosomi (MNS) names a whole marked phrase, not this word alone. A Fijian object example remains to be checked.', '{"role":{"fijian":"isosomi","english":"first-person pronoun in object use; the whole phrase role needs a cited example"},"relatedWords":["yau"],"comparison":"Au refers to the speaker: it can mean I in subject use or me in object use. Yau can also mean me in a suitable phrase; the full sentence shows the role.","furtherLink":{"label":"Explore au in Object licensing in Fijian and the role of adjacency (2019)","href":"https://link.springer.com/article/10.1007/s11049-019-09442-1"},"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Founder-supplied object use of an isosomi form. Matanauni sosomi (MNS) names a whole marked phrase, not this word alone. A Fijian object example remains to be checked."}}', '[{"sourceId":"naisema-founder-pronouns-2026-11-01"},{"sourceId":"fijian-object-licensing-2019"},{"sourceId":"naisema-founder-au-yau-aua-auwa-2026-11-03"}]', '["pronouns"]', 'au | me (object use) | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('9a2458d0fdd2cc3c', 'standard-fijian', 'word', 'keirau', 'keirau', 'pronoun', 'us two, excluding you (object use)', '', '', '', 'Founder-supplied object use of an isosomi form. Matanauni sosomi (MNS) names a whole marked phrase, not this word alone. A Fijian object example remains to be checked.', '{"role":{"fijian":"isosomi","english":"first-person pronoun in object use; the whole phrase role needs a cited example"},"relatedWords":["kedaru"],"comparison":"Keirau excludes the listener; kedaru/daru includes the listener. Keirau is dual (two people).","furtherLink":{"label":"Explore keirau in Object licensing in Fijian and the role of adjacency (2019)","href":"https://link.springer.com/article/10.1007/s11049-019-09442-1"},"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Founder-supplied object use of an isosomi form. Matanauni sosomi (MNS) names a whole marked phrase, not this word alone. A Fijian object example remains to be checked."}}', '[{"sourceId":"naisema-founder-pronouns-2026-11-01"},{"sourceId":"fijian-object-licensing-2019"}]', '["pronouns"]', 'keirau | us two, excluding you (object use) | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
