INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('eb6d80734f08d1f4', 'standard-fijian', 'word', 'keitou', 'keitou', 'pronoun', 'us few, three or more in a small group, excluding you (object use)', '', '', '', 'Founder-supplied object use of an isosomi form. Matanauni sosomi (MNS) names a whole marked phrase, not this word alone. A Fijian object example remains to be checked.', '{"role":{"fijian":"isosomi","english":"first-person pronoun in object use; the whole phrase role needs a cited example"},"relatedWords":["keimami","kedatou"],"comparison":"Keitou excludes the listener and is paucal (a few people); keimami is plural (many).","furtherLink":{"label":"Explore keitou in Object licensing in Fijian and the role of adjacency (2019)","href":"https://link.springer.com/article/10.1007/s11049-019-09442-1"},"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Founder-supplied object use of an isosomi form. Matanauni sosomi (MNS) names a whole marked phrase, not this word alone. A Fijian object example remains to be checked."}}', '[{"sourceId":"naisema-founder-pronouns-2026-11-01"},{"sourceId":"fijian-object-licensing-2019"}]', '["pronouns"]', 'keitou | us few, three or more in a small group, excluding you (object use) | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
