INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('e2889c5fe69115fa', 'standard-fijian', 'word', 'keda', 'keda', 'pronoun', 'us many, including you and me; the group may be a village (object use)', '', '', '', 'Founder-supplied object use of an isosomi form. Matanauni sosomi (MNS) names a whole marked phrase, not this word alone. A Fijian object example remains to be checked.', '{"role":{"fijian":"isosomi","english":"first-person pronoun in object use; the whole phrase role needs a cited example"},"relatedWords":["keimami","da"],"comparison":"Keda is the full inclusive plural pronoun; da is a shorter form in this set.","furtherLink":{"label":"Explore keda in Object licensing in Fijian and the role of adjacency (2019)","href":"https://link.springer.com/article/10.1007/s11049-019-09442-1"},"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Founder-supplied object use of an isosomi form. Matanauni sosomi (MNS) names a whole marked phrase, not this word alone. A Fijian object example remains to be checked."}}', '[{"sourceId":"naisema-founder-pronouns-2026-11-01"},{"sourceId":"fijian-object-licensing-2019"}]', '["pronouns"]', 'keda | us many, including you and me; the group may be a village (object use) | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
