INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('88c8d23bceb551e6', 'standard-fijian', 'word', 'bisikete', 'bisikete', 'noun', 'Biscuits; small baked snacks.', '', '', '', 'Owner confirmed the spelling bisikete and the English meaning. Fijian sentence and Tuvavosa role need review.', '{"relatedWords":["keke","Ti"],"comparison":"Bisikete means biscuits; keke means cake. Both are baked foods, but they are not the same item.","learnerComment":"The packet can empty surprisingly fast once the tea comes out.","imageLinks":[{"label":"Wikimedia Commons · biscuits","url":"https://commons.wikimedia.org/wiki/Category:Biscuits"}],"searchKeywords":["cookie","cookies","baked snack","tea snack"],"exploration":{"title":"How biscuit became bisikete","text":"Bisikete is a Fijian borrowing from English biscuit. Its final vowel belongs to the Fijian form. Bisikete means biscuits, while keke means cake; the shared baking theme does not make them the same food.","question":"What happens to the end of English biscuit when you say bisikete?"},"furtherLink":{"label":"Explore research on English loanwords in Fijian","href":"https://openresearch-repository.anu.edu.au/server/api/core/bitstreams/78ff8d53-4142-446c-84cb-507a8a6ff982/content"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Owner confirmed the spelling bisikete and the English meaning. Fijian sentence and Tuvavosa role need review."}}', '[{"sourceId":"naisema-founder-food-2026-11-01"}]', '["baked-foods","food"]', 'bisikete | biscuits; small baked snacks. | | | cookie | cookies | baked snack | tea snack', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('b7506d50ce1b7c30', 'standard-fijian', 'word', 'keke', 'keke', 'noun', 'Cake; a sweet baked food.', '', '', '', 'Owner supplied the English meaning. Fijian sentence and Tuvavosa role need review.', '{"relatedWords":["Pae","madrai"],"comparison":"Keke is cake; Pae is pie. A pie has a pastry base or case around its filling, while a cake is a baked batter.","learnerComment":"The one everyone hopes has a generous slice left.","imageLinks":[{"label":"Wikimedia Commons · cakes","url":"https://commons.wikimedia.org/wiki/Category:Cakes"}],"searchKeywords":["dessert","baked treat","sweet baked food"],"exploration":{"title":"How cake became keke","text":"Keke came from English cake, reshaped to fit Fijian sounds. Pae names a pie: its pastry case makes it a different kind of baked food.","question":"If you heard keke before seeing the food, what clue in the word might help you recognise its English source?"},"furtherLink":{"label":"See keke in research on Fijian loanword sounds","href":"https://journals.linguisticsociety.org/proceedings/index.php/amphonology/article/download/3651/3454/4826"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Owner supplied the English meaning. Fijian sentence and Tuvavosa role need review."}}', '[{"sourceId":"naisema-founder-food-2026-11-01"}]', '["baked-foods","food"]', 'keke | cake; a sweet baked food. | | | dessert | baked treat | sweet baked food', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('de95887982f713d6', 'standard-fijian', 'word', 'Pae', 'pae', 'noun', 'Pie; a baked pastry dish with a filling.', '', '', '', 'Owner supplied the English meaning. Fijian sentence and Tuvavosa role need review.', '{"relatedWords":["keke"],"comparison":"Pae is pie, not keke (cake). English uses pie for a pastry dish and cake for a different kind of baked food.","learnerComment":"The filling might be sweet or savoury; the pastry is the clue.","imageLinks":[{"label":"Wikimedia Commons · pies","url":"https://commons.wikimedia.org/wiki/Category:Pies"}],"searchKeywords":["pastry","pastry dish","baked filling"],"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Owner supplied the English meaning. Fijian sentence and Tuvavosa role need review."}}', '[{"sourceId":"naisema-founder-food-2026-11-01"}]', '["baked-foods","food"]', 'pae | pie; a baked pastry dish with a filling. | | | pastry | pastry dish | baked filling', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('7fd9b16ee02e125a', 'standard-fijian', 'word', 'ti', 'ti', 'noun', 'Tea; the drink.', '', '', '', 'Owner supplied the English meaning. Fijian sentence and Tuvavosa role need review.', '{"relatedWords":["bisikete"],"comparison":"This ti means tea. Other entries spelled Ti have different meanings, so the sentence must tell us which sense is intended.","learnerComment":"A cup of ti and a biscuit make a pretty good break.","imageLinks":[{"label":"Wikimedia Commons · tea","url":"https://commons.wikimedia.org/wiki/Category:Tea"}],"searchKeywords":["hot drink","beverage","teatime"],"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Owner supplied the English meaning. Fijian sentence and Tuvavosa role need review."}}', '[{"sourceId":"naisema-founder-food-2026-11-01"}]', '["food"]', 'ti | tea; the drink. | | | hot drink | beverage | teatime', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
