INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('naisema-culture-veiqaraqaravi-vakavanua', 'standard-fijian', 'word', 'veiqaraqaravi vakavanua', 'veiqaraqaravi-vakavanua', 'phrase', 'A formal Fijian traditional welcome or ceremonial reception, especially for an honoured visitor.', '', '', '', 'Both spellings occur in institutional use. Check local preference and a complete Fijian sentence before approving the Tuvavosa role.', '{"relatedWords":["i sevusevu","tabua","yaqona","lakolako vakavulagi","itatau","qaloqalovi"],"comparison":"Veiqaraqaravi vakavanua names the welcome; i sevusevu names a customary presentation within a welcome. Tabua is an object that may be presented, while yaqona names kava.","learnerComment":"This names the welcome as a whole. The words for a presentation or an item used during it name different things.","imageLinks":[{"label":"See a Fiji government welcome","url":"https://www.corrections.gov.fj/opening-of-the-northern-division-headquarters-in-vaturekuka-labasa/"}],"searchKeywords":["traditional welcome","Fijian ceremony","ceremonial reception","cultural welcome","veiqaravi vakavanua"],"furtherLink":{"label":"Explore veiqaraqaravi vakavanua in Fiji Corrections Service · Northern Division opening, 2025","href":"https://www.corrections.gov.fj/opening-of-the-northern-division-headquarters-in-vaturekuka-labasa/"},"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Both spellings occur in institutional use. Check local preference and a complete Fijian sentence before approving the Tuvavosa role."}}', '[{"sourceId":"fiji-corrections-veiqaraqaravi-2025"},{"sourceId":"fiji-foreign-affairs-veiqaravi-2026"}]', '["customs","veiqaraqaravi-vakavanua"]', 'veiqaraqaravi vakavanua | a formal fijian traditional welcome or ceremonial reception, especially for an honoured visitor. | | | traditional welcome | fijian ceremony | ceremonial reception | cultural welcome | veiqaravi vakavanua', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('naisema-culture-i-sevusevu', 'standard-fijian', 'word', 'i sevusevu', 'i-sevusevu', 'noun', 'A customary presentation used to introduce visitors to their hosts and show respect; it may involve yaqona.', '', '', '', 'English use is supported by a first-person institutional account. A complete Fijian sentence and local scope remain to be checked.', '{"relatedWords":["veiqaraqaravi vakavanua","yaqona","tabua","qaloqalovi","icavuti","itatau"],"comparison":"I sevusevu names a presentation made by visitors. Veiqaraqaravi vakavanua names the wider welcome in which presentations can take place.","learnerComment":"In one recorded Fiji welcome, visitors offered a bale of yaqona as their i sevusevu.","imageLinks":[{"label":"See this Fiji welcome account","url":"https://isa.org.jm/news/madam-secretary-general-reflects-on-her-mission-to-fiji-and-the-opening-of-the-pacific-sids-regional-workshop/"}],"searchKeywords":["sevusevu","ceremonial presentation","traditional welcome","kava offering","sevusevu"],"exploration":{"title":"The presentation and the welcome","question":"During a visit, how does the i sevusevu fit into the wider welcome?"},"furtherLink":{"label":"Explore i sevusevu in International Seabed Authority · Fiji welcome account, 2026","href":"https://isa.org.jm/news/madam-secretary-general-reflects-on-her-mission-to-fiji-and-the-opening-of-the-pacific-sids-regional-workshop/"},"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"English use is supported by a first-person institutional account. A complete Fijian sentence and local scope remain to be checked."}}', '[{"sourceId":"isa-fiji-welcome-2026"}]', '["customs","veiqaraqaravi-vakavanua"]', 'i sevusevu | a customary presentation used to introduce visitors to their hosts and show respect; it may involve yaqona. | | | sevusevu | ceremonial presentation | traditional welcome | kava offering | sevusevu', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('naisema-culture-tabua', 'standard-fijian', 'word', 'tabua', 'tabua', 'noun', 'A sperm whale tooth used as an important ceremonial presentation in Fiji.', '', '', '', 'Check this meaning and its use in a complete Fijian phrase before approving it.', '{"relatedWords":["i sevusevu","veiqaraqaravi vakavanua","yaqona","kamunaga","boka","itatau"],"comparison":"Tabua names the ceremonial tooth. I sevusevu names a customary presentation, which may instead involve yaqona; veiqaraqaravi vakavanua names the wider welcome.","learnerComment":"The object is a tabua; the act of presenting it has its own name and purpose in a particular ceremony.","imageLinks":[{"label":"See Fijian tabua objects","url":"https://commons.wikimedia.org/wiki/Category:Objects_of_Fiji"}],"searchKeywords":["whale tooth","ceremonial tooth","traditional gift","Fijian welcome"],"furtherLink":{"label":"Explore tabua in International Seabed Authority · Fiji welcome account, 2026","href":"https://isa.org.jm/news/madam-secretary-general-reflects-on-her-mission-to-fiji-and-the-opening-of-the-pacific-sids-regional-workshop/"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"The independently written public meaning is separate from an older private source record. A Fijian sentence and local usage remain to be checked."}}', '[{"sourceId":"isa-fiji-welcome-2026"}]', '["customs","veiqaraqaravi-vakavanua"]', 'tabua | a sperm whale tooth used as an important ceremonial presentation in fiji. | | | whale tooth | ceremonial tooth | traditional gift | fijian welcome', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('naisema-guide-lakolako-vakavulagi', 'standard-fijian', 'word', 'lakolako vakavulagi', 'lakolako-vakavulagi', 'cultural term', 'A delegation making a formal visit to another community.', '', '', '', 'Original English learning summary. Check exact local practice, spelling, and a complete Fijian example before approving this sense.', '{"relatedWords":["vulagi","itaukei"],"comparison":"Lakolako vakavulagi names the visiting delegation as a group; vulagi names a visitor or guest, while itaukei names the receiving side.","learnerComment":"The name identifies a part of an exchange; the local occasion decides exactly how it is done.","searchKeywords":["visiting delegation","formal visit","guests"],"appsSite":{"englishChecked":false,"status":"needs review; meaning needs review","notes":"Original English learning summary. Check exact local practice, spelling, and a complete Fijian example before approving this sense."}}', '[{"sourceId":"bula-vakavanua-wase-5-owner-2026-11-01","section":"Wase 5"}]', '["customs","veiqaraqaravi-vakavanua"]', 'lakolako vakavulagi | a delegation making a formal visit to another community. | | | visiting delegation | formal visit | guests', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('naisema-guide-itaukei', 'standard-fijian', 'word', 'itaukei', 'itaukei', 'cultural term', 'The receiving people or hosts in a formal visiting exchange.', '', '', '', 'Original English learning summary. Check exact local practice, spelling, and a complete Fijian example before approving this sense.', '{"relatedWords":["vulagi","lakolako vakavulagi"],"comparison":"In this visiting exchange, itaukei are the hosts and vulagi are the visitors. The words identify different positions in the same relationship.","learnerComment":"The name identifies a part of an exchange; the local occasion decides exactly how it is done.","searchKeywords":["hosts","receiving community","traditional visit"],"appsSite":{"englishChecked":false,"status":"needs review; meaning needs review","notes":"Original English learning summary. Check exact local practice, spelling, and a complete Fijian example before approving this sense."}}', '[{"sourceId":"bula-vakavanua-wase-5-owner-2026-11-01","section":"Wase 5"}]', '["customs","veiqaraqaravi-vakavanua"]', 'itaukei | the receiving people or hosts in a formal visiting exchange. | | | hosts | receiving community | traditional visit', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('naisema-guide-vulagi', 'standard-fijian', 'word', 'vulagi', 'vulagi', 'cultural term', 'A visitor or guest in a formal exchange with a receiving community.', '', '', '', 'Original English learning summary. Check exact local practice, spelling, and a complete Fijian example before approving this sense.', '{"relatedWords":["itaukei","lakolako vakavulagi"],"comparison":"Vulagi identifies the visitor; itaukei identifies the receiving people. Vulagi can also mean a stranger in another context.","learnerComment":"The name identifies a part of an exchange; the local occasion decides exactly how it is done.","searchKeywords":["guest","visitor","delegation"],"appsSite":{"englishChecked":false,"status":"needs review; meaning needs review","notes":"Original English learning summary. Check exact local practice, spelling, and a complete Fijian example before approving this sense."}}', '[{"sourceId":"bula-vakavanua-wase-5-owner-2026-11-01","section":"Wase 5"}]', '["customs","veiqaraqaravi-vakavanua"]', 'vulagi | a visitor or guest in a formal exchange with a receiving community. | | | guest | visitor | delegation', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('naisema-guide-boka', 'standard-fijian', 'word', 'boka', 'boka', 'cultural term', 'A ceremonial presentation acknowledging a death in the receiving community while visitors were away.', '', '', '', 'Original English learning summary. Check exact local practice, spelling, and a complete Fijian example before approving this sense.', '{"relatedWords":["tabua","veiwekani"],"comparison":"Boka acknowledges a death during the visitors’ absence; sevusevu opens a visit. A tabua may be presented, but it names the object rather than the act.","learnerComment":"The name identifies a part of an exchange; the local occasion decides exactly how it is done.","searchKeywords":["mourning presentation","death acknowledgement","traditional visit"],"appsSite":{"englishChecked":false,"status":"needs review; meaning needs review","notes":"Original English learning summary. Check exact local practice, spelling, and a complete Fijian example before approving this sense."}}', '[{"sourceId":"bula-vakavanua-wase-5-owner-2026-11-01","section":"Wase 5"}]', '["customs","veiqaraqaravi-vakavanua"]', 'boka | a ceremonial presentation acknowledging a death in the receiving community while visitors were away. | | | mourning presentation | death acknowledgement | traditional visit', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('naisema-guide-icavuti', 'standard-fijian', 'word', 'icavuti', 'icavuti', 'cultural term', 'A traditional title or form of identification used to acknowledge a person, authority, or place in ceremonial speech.', '', '', '', 'Original English learning summary. Check exact local practice, spelling, and a complete Fijian example before approving this sense.', '{"relatedWords":["i sevusevu","veidokadokai"],"comparison":"Icavuti is the title or identification used in ceremonial speech; sevusevu is a presentation in which that identification may matter.","learnerComment":"The name identifies a part of an exchange; the local occasion decides exactly how it is done.","searchKeywords":["traditional title","ceremonial address","identity"],"exploration":{"title":"A title belongs to a community level","question":"When you visit a village, does the icavuti you hear belong to the yasana, tikina, koro, or a more specific group?"},"furtherLink":{"label":"Explore Icavuti by place","href":"/apps/dictionary/"},"appsSite":{"englishChecked":false,"status":"needs review; meaning needs review","notes":"Original English learning summary. Check exact local practice, spelling, and a complete Fijian example before approving this sense."}}', '[{"sourceId":"bula-vakavanua-wase-5-owner-2026-11-01","section":"Wase 5"}]', '["customs","veiqaraqaravi-vakavanua"]', 'icavuti | a traditional title or form of identification used to acknowledge a person, authority, or place in ceremonial speech. | | | traditional title | ceremonial address | identity', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('naisema-guide-kamunaga', 'standard-fijian', 'word', 'kamunaga', 'kamunaga', 'cultural term', 'A valued ceremonial object, especially a tabua, used in a presentation appropriate to the occasion.', '', '', '', 'Original English learning summary. Check exact local practice, spelling, and a complete Fijian example before approving this sense.', '{"relatedWords":["tabua","itatau"],"comparison":"Kamunaga is a valued item in a ceremonial exchange; tabua names one specific kind of such item.","learnerComment":"The name identifies a part of an exchange; the local occasion decides exactly how it is done.","searchKeywords":["ceremonial valuable","traditional presentation","tabua"],"appsSite":{"englishChecked":false,"status":"needs review; meaning needs review","notes":"Original English learning summary. Check exact local practice, spelling, and a complete Fijian example before approving this sense."}}', '[{"sourceId":"bula-vakavanua-wase-5-owner-2026-11-01","section":"Wase 5"}]', '["customs","veiqaraqaravi-vakavanua"]', 'kamunaga | a valued ceremonial object, especially a tabua, used in a presentation appropriate to the occasion. | | | ceremonial valuable | traditional presentation | tabua', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
