INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('naisema-guide-meke', 'standard-fijian', 'word', 'meke', 'meke', 'cultural term', 'A traditional performance that can honour or entertain visitors after formal exchanges.', '', '', '', 'Original English learning summary. Check exact local practice, spelling, and a complete Fijian example before approving this sense.', '{"relatedWords":["yaqona vakaturaga","qaloqalovi"],"comparison":"Meke is performance; yaqona vakaturaga is a formal chiefly yaqona ceremony. They can occur in the same reception but serve different purposes.","learnerComment":"The name identifies a part of an exchange; the local occasion decides exactly how it is done.","searchKeywords":["dance","traditional performance","celebration"],"appsSite":{"englishChecked":false,"status":"needs review; meaning needs review","notes":"Original English learning summary. Check exact local practice, spelling, and a complete Fijian example before approving this sense."}}', '[{"sourceId":"bula-vakavanua-wase-5-owner-2026-11-01","section":"Wase 5"}]', '["customs","veiqaraqaravi-vakavanua"]', 'meke | a traditional performance that can honour or entertain visitors after formal exchanges. | | | dance | traditional performance | celebration', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
