INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('2b2c62b09e6f7267', 'standard-fijian', 'word', 'Leva', 'leva', 'verb', 'To take offence or feel resentful when someone raises a matter you would rather not discuss.', '', '', '', 'Owner corrected the headword and meaning. The example is attested; the exact Tuvavosa role still needs review.', '{"usageExamples":[{"fijian":"Au sega ni cudru se leva e na vuku ni lomatarotaro.","english":"I am not angry or offended by the questioning."}],"relatedWords":["cudru"],"comparison":"Cudru is anger more generally. Leva focuses on feeling offended or resentful by a remark, question, or unwelcome issue.","learnerComment":"Sometimes a question feels personal, even when the person asking did not mean it that way.","searchKeywords":["offended","offence","take offense","resentful","resentment","touchy","unwelcome question"],"furtherLink":{"label":"Explore Leva in The Fiji Times · Vola ni Kawa Bula","href":"https://www.fijitimes.com.fj/vola-ni-kawa-bula/"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Owner corrected the headword and meaning. The example is attested; the exact Tuvavosa role still needs review."}}', '[{"sourceId":"naisema-owner-leva-2026-11-02"},{"sourceId":"fiji-times-leva-questioning-2016"},{"sourceId":"fijian-leva-rai-cala-2015"}]', '["feelings"]', 'leva | to take offence or feel resentful when someone raises a matter you would rather not discuss. | | | offended | offence | take offense | resentful | resentment | touchy | unwelcome question', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
