INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('1bdc11eb0de0cc95', 'standard-fijian', 'word', 'bia', 'bia', 'noun', 'Beer, the brewed alcoholic drink.', '', '', '', '', '{"usageExamples":[{"fijian":"Oqo na mequ bia.","english":"This is my beer to drink."}],"relatedWords":["yaqona","mequ"],"comparison":"Bia names beer, while yaqona names kava. In mequ bia, mequ marks the beer as the speaker''s to drink; English ''my beer'' does not reveal that use.","searchKeywords":["beer","alcoholic drink"],"furtherLink":{"label":"Explore bia in Schutz and Komaitai, Lessons in Fijian, Peace Corps (1968)","href":"https://files.eric.ed.gov/fulltext/ED131693.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"peace-corps-lessons-fijian-1968"},{"sourceId":"hong-fijian-pronouns-1994"}]', '["food"]', 'bia | beer, the brewed alcoholic drink. | | | beer | alcoholic drink', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
