INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('39cdf5d9215cc0fb', 'standard-fijian', 'word', 'yanuyanu', 'yanuyanu', 'noun', 'An island, especially a small one.', '', '', '', '', '{"learnerComment":"The word can identify a small island. The wider name Vanua Levu does not use yanuyanu as its ordinary label.","furtherLink":{"label":"Explore yanuyanu in Unitec · Fijian-English vocabulary","href":"https://www.unitec.ac.nz/umisc/jmctest/fijian_english_dictionary/fijian_eng_dict.html"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"unitec-vocab-english-review"}]', '["places"]', 'yanuyanu | an island, especially a small one. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
