INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('c499cbc9051c8c96', 'standard-fijian', 'word', 'yadra', 'yadra', 'verb', 'Awake; to wake up.', '', '', '', '', '{"learnerComment":"The same word also appears in a morning greeting, so a sentence can be about waking or about greeting someone.","curiosityQuestion":"Is yadra describing someone who has woken, or greeting them?","furtherLink":{"label":"Explore yadra in Unitec · Fijian-English vocabulary","href":"https://www.unitec.ac.nz/umisc/jmctest/fijian_english_dictionary/fijian_eng_dict.html"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"unitec-vocab-english-review"}]', '[]', 'yadra | awake; to wake up. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
