--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('a6e0c0af2750bd23', 'standard-fijian', 'word', 'delana', 'delana', 'noun', 'A hilltop or the top of a hill.', '', '', '', '', '{"learnerComment":"From a delana, a speaker may describe what can be seen in different directions.","furtherLink":{"label":"Explore delana in Peace Corps Fijian lessons, ERIC ED131693","href":"https://files.eric.ed.gov/fulltext/ED131693.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"peace-corps-fijian-lessons-english-review"}]', '[]', 'delana | a hilltop or the top of a hill. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
