INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('56875825e68dab9e', 'standard-fijian', 'word', 'yakavi', 'yakavi', 'noun', 'The late afternoon or early evening.', '', '', '', '', '{"learnerComment":"Yakavi stretches toward dusk. In a time phrase, tolu ena yakavi puts three o’clock in the afternoon.","searchKeywords":["late afternoon","early evening"],"furtherLink":{"label":"Explore yakavi in Peace Corps Fijian lessons, ERIC ED131693","href":"https://files.eric.ed.gov/fulltext/ED131693.pdf"},"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"peace-corps-fijian-lessons-english-review"}]', '["time"]', 'yakavi | the late afternoon or early evening. | | | late afternoon | early evening', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
