INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('6e7b6f78f81997fc', 'standard-fijian', 'word', 'maca', 'maca', 'verb', 'Empty or used up, especially of a liquid; dry.', '', '', '', '', '{"learnerComment":"When the water has run out, maca says there is none left in the container.","curiosityQuestion":"If a cup is maca, is it still waiting to be filled or already finished?","furtherLink":{"label":"Explore maca in Peace Corps Fijian lessons, ERIC ED131693","href":"https://files.eric.ed.gov/fulltext/ED131693.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"peace-corps-fijian-lessons-english-review"}]', '[]', 'maca | empty or used up, especially of a liquid; dry. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('8520af742bd065ac', 'standard-fijian', 'word', 'katakata', 'katakata', 'adjective', 'Hot, whether from heat or spicy food.', '', '', '', '', '{"learnerComment":"Katakata can describe hot water and also the heat of chilli in a meal. The thing being described tells you which heat is meant.","furtherLink":{"label":"Explore katakata in Peace Corps Fijian lessons, ERIC ED131693","href":"https://files.eric.ed.gov/fulltext/ED131693.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"peace-corps-fijian-lessons-english-review"}]', '[]', 'katakata | hot, whether from heat or spicy food. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
