--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('01df5ae72190120b', 'standard-fijian', 'word', 'tidaloko', 'tidaloko', 'noun', 'A mudskipper found around Fiji''s mangroves.', '', '', '', '', '{"learnerComment":"Tidaloko is a fish that moves over exposed mud and mangrove roots, where water and land meet. Tiloko is another recorded form.","searchKeywords":["fish of Fiji","coastal fish"],"furtherLink":{"label":"Explore tidaloko in Fiji mangrove reforestation project fauna checklist","href":"https://gec.jp/jpn/cdm-fs/2005/200516JPAnnex-TaishiDesignOffice-Fiji-MangroveReforestation.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"fiji-mangrove-checklist"}]', '["fiji-fish","sea-life"]', 'tidaloko | a mudskipper found around fiji''s mangroves. | | | fish of fiji | coastal fish', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('486f4b6a1b9a0e32', 'standard-fijian', 'word', 'moka', 'moka', 'noun', 'A stone fish trap built along the shore.', '', '', '', '', '{"learnerComment":"A moka uses the tide: fish enter when the water rises and remain inside its stone enclosure as the water falls. Villagers on Koro have maintained such traps across generations.","searchKeywords":["stone fish trap","tidal fish trap"],"furtherLink":{"label":"Explore moka in Fiji Times, stone fish traps on Koro","href":"https://www.fijitimes.com.fj/discovering-fiji-the-fish-trap-and-leka-the-spirit/"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"fijitimes-koro-moka"}]', '["fishing-traps","coast"]', 'moka | a stone fish trap built along the shore. | | | stone fish trap | tidal fish trap', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('cfee6b4aa59fa53c', 'standard-fijian', 'word', 'vuvu', 'vuvu', 'noun', 'A narrow bamboo fish trap.', '', '', '', '', '{"learnerComment":"Vuvu is a woven or bamboo trap placed for fish, unlike a moka, which is built from stones along the shore. The same spelling has several other meanings, so the fishing context matters.","searchKeywords":["bamboo fish trap","river trap"],"furtherLink":{"label":"Explore vuvu in The Lexicon of Proto Oceanic, fishing and hunting","href":"https://tlopo.clld.org/contributions/1-8"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"proto-oceanic-fishing"}]', '["fishing-traps"]', 'vuvu | a narrow bamboo fish trap. | | | bamboo fish trap | river trap', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('2e2de5f840661039', 'standard-fijian', 'word', 'qolua', 'qolua', 'noun', 'A hollow-bamboo trap used in rivers, particularly for eels.', '', '', '', '', '{"learnerComment":"Qolua uses a bamboo tube to catch fish in fresh water. Compare the bamboo trap vuvu and the shoreline stone trap moka: their materials and settings differ.","searchKeywords":["bamboo fish trap","eel trap"],"furtherLink":{"label":"Explore qolua in WCS Fiji Fishery Resource Profiles","href":"https://fiji.wcs.org/Portals/82/WCS%20Fisheries%20Profile%20290920%20WEB%20%281%29.pdf?ver=2020-10-14-024200-580"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"wcs-profiles-2020"}]', '["fishing-traps"]', 'qolua | a hollow-bamboo trap used in rivers, particularly for eels. | | | bamboo fish trap | eel trap', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('fcdfba4238fa9951', 'standard-fijian', 'word', 'sara', 'sara', 'noun', 'A small, silvery coastal fish known as a silverside.', '', '', '', '', '{"learnerComment":"Sara can gather in schools near shore and be used as bait. Sara also has unrelated meanings in Fijian; the fish sense depends on the context.","searchKeywords":["fish of Fiji","coastal fish"],"furtherLink":{"label":"Explore sara in SPC, finfishes of Vanua Navakavu","href":"https://spccfpstore1.blob.core.windows.net/digitallibrary-docs/files/88/88a1f351144fda547a2b74821378837f.pdf"},"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"spc-vanua-navakavu-fish"}]', '["fiji-fish","sea-life"]', 'sara | a small, silvery coastal fish known as a silverside. | | | fish of fiji | coastal fish', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('01dcd00871be9040', 'standard-fijian', 'word', 'sarau', 'sarau', 'noun', 'A small yellow reef snapper with blue lines, also called kake in some fish lists.', '', '', '', '', '{"learnerComment":"The yellow body and blue lengthwise lines help distinguish sarau from other snappers. Recorded scientific identifications vary, so this entry does not fix it to one species.","searchKeywords":["fish of Fiji","reef fish"],"furtherLink":{"label":"Explore sarau in University of the South Pacific, Explanation for Fiji Fishes","href":"https://fjdigitallib.usp.ac.fj/greenstone3/pimris/sites/pimrissite/collect/pimris/index/assoc/HASH5247.dir/doc.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"usp-food-fishes"}]', '["fiji-fish","sea-life"]', 'sarau | a small yellow reef snapper with blue lines, also called kake in some fish lists. | | | fish of fiji | reef fish', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('713eb4339b09a0fa', 'standard-fijian', 'word', 'moci', 'moci', 'noun', 'Small edible prawns or shrimps of mangrove and estuary waters.', '', '', '', '', '{"learnerComment":"Moci are collected in shallow mangrove pools and are eaten or sold. In parts of the Rewa delta they are a familiar local food; the name does not by itself fix one prawn species.","searchKeywords":["small prawn","mangrove shrimp","coastal seafood"],"furtherLink":{"label":"Explore moci in Women in Fisheries Fiji, Role and Engagement of Women in Fisheries","href":"https://womeninfisheriesfiji.org/wp-content/uploads/2016/10/The-Role-Engagement-of-Women-in-Fisheries-in-Fiji-1.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"women-in-fisheries-moci"}]', '["sea-life"]', 'moci | small edible prawns or shrimps of mangrove and estuary waters. | | | small prawn | mangrove shrimp | coastal seafood', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('2debc3d484a9e519', 'standard-fijian', 'word', 'dai', 'dai', 'noun', 'A snare or trap for catching an animal.', '', '', '', '', '{"learnerComment":"Dai can be a small catching device rather than the larger fixed stone enclosure called moka. The particular target and construction need local context.","searchKeywords":["animal snare","trap"],"furtherLink":{"label":"Explore dai in The Lexicon of Proto Oceanic, fishing and hunting","href":"https://tlopo.clld.org/contributions/1-8"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"proto-oceanic-fishing"}]', '["fishing-traps"]', 'dai | a snare or trap for catching an animal. | | | animal snare | trap', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('29f3e91748dd5621', 'standard-fijian', 'word', 'itaraki', 'itaraki', 'noun', 'A small hand-held fishing net.', '', '', '', '', '{"learnerComment":"In a Kadavu fisherwoman''s account, each woman used her own taraki to scoop schooling fish; several could bring their nets together when a catch tried to escape. Itaraki is the instrument form in this entry.","searchKeywords":["hand net","small fishing net"],"furtherLink":{"label":"Explore itaraki in Fiji school Fijian language study package, Year 8","href":"https://sangamedu.ac.fj/wp-content/uploads/2021/12/Home-Study-Package-Year-8-2.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"fiji-school-itaraki"},{"sourceId":"ambio-kadavu-fishing"}]', '["fishing-traps"]', 'itaraki | a small hand-held fishing net. | | | hand net | small fishing net', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('9c592b7f82fdd83b', 'standard-fijian', 'word', 'bati-ni-siwa', 'bati-ni-siwa', 'noun', 'A fish-hook.', '', '', '', '', '{"learnerComment":"Bati ni siwa names the hook; wa ni siwa names the line. A historic Fijian hook is held in the Auckland War Memorial Museum collection.","searchKeywords":["fish hook","fishing tackle"],"furtherLink":{"label":"Explore bati-ni-siwa in Auckland War Memorial Museum, Fiji fishing tools","href":"https://artsandculture.google.com/story/nai-ya-vakaviki-na-ka-mareqeti-fiji-auckland-war-memorial-museum/FwXhbA0kX3gnJw?hl=en"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"auckland-fiji-fishing-tools"}]', '["fishing-traps"]', 'bati-ni-siwa | a fish-hook. | | | fish hook | fishing tackle', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('67b3807e1c6c3bee', 'standard-fijian', 'word', 'wa ni siwa', 'wa-ni-siwa', 'noun', 'A fishing line.', '', '', '', '', '{"usageExamples":[{"fijian":"Sā vinaka, me''u sā la''ki vaka-rautaka mada na neirau wā ni siwa.","english":"All right, I''ll go and get our fishing line ready now."}],"learnerComment":"Wa ni siwa is the line, while bati ni siwa is the hook attached to it. Both parts have their own names.","searchKeywords":["fishing line","fishing tackle"],"furtherLink":{"label":"Explore wa ni siwa in Peace Corps, Fijian language lesson 8","href":"https://fsi-languages.yojik.eu/languages/PeaceCorps/Fijian/ED131693.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"peace-corps-fijian-dialogue"}]', '["fishing-traps"]', 'wa ni siwa | a fishing line. | | | fishing line | fishing tackle', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('0f5b343d2abb2dcd', 'standard-fijian', 'word', 'qoliva', 'qoliva', 'verb', 'To go fishing or fish in a particular stretch of water.', '', '', '', '', '{"learnerComment":"Qoliva appears with na wai in a Fijian account of fishing nearby water. The phrase helps show the place being fished; further examples are needed to settle its full grammatical range.","searchKeywords":["go fishing","fishing in a place"],"furtherLink":{"label":"Explore qoliva in Fiji Times, Yavu ni veiqaravi","href":"https://www.fijitimes.com.fj/yavu-ni-veiqaravi-o-keda-kei-na-iyaubula/"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"fijitimes-qoliva"}]', '["fishing-traps"]', 'qoliva | to go fishing or fish in a particular stretch of water. | | | go fishing | fishing in a place', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('605443eb0dab591e', 'standard-fijian', 'word', 'iqoliqoli', 'iqoliqoli', 'noun', 'A customary fishing area associated with a local community.', '', '', '', '', '{"learnerComment":"Iqoliqoli refers to the fishing grounds and the community rights connected with them. That is different from qoli, the activity of fishing.","searchKeywords":["customary fishing ground","community fishing area"],"furtherLink":{"label":"Explore iqoliqoli in Tourism Fiji, Fishing in Fiji","href":"https://www.fiji.travel/things-to-do/charters/fiji-fishing"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"tourism-fiji-fishing"}]', '["fishing-traps","coast"]', 'iqoliqoli | a customary fishing area associated with a local community. | | | customary fishing ground | community fishing area', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('4580eda4041c6726', 'standard-fijian', 'word', 'qari', 'qari', 'noun', 'A mangrove or mud crab.', '', '', '', '', '{"learnerComment":"Qari lives around mangrove habitat. Compare lairo, a land crab: the two are both eaten in Fiji but belong to different coastal habitats.","searchKeywords":["coastal seafood","crustacean"],"furtherLink":{"label":"Explore qari in WCS Fiji Fishery Resource Profiles","href":"https://fiji.wcs.org/Portals/82/WCS%20Fisheries%20Profile%20290920%20WEB%20%281%29.pdf?ver=2020-10-14-024200-580"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"wcs-profiles-2020"}]', '["sea-life"]', 'qari | a mangrove or mud crab. | | | coastal seafood | crustacean', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('640a0560d69d21ad', 'standard-fijian', 'word', 'lairo', 'lairo', 'noun', 'A large edible land crab found in coastal Fiji.', '', '', '', '', '{"learnerComment":"Lairo is a land crab; qari is the swimming mangrove or mud crab. The shared English word ''crab'' hides that difference.","searchKeywords":["coastal animal","land crab"],"furtherLink":{"label":"Explore lairo in Frontiers in Marine Science, fisherwomen''s knowledge in Fiji","href":"https://www.frontiersin.org/journals/marine-science/articles/10.3389/fmars.2022.991253/full"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"frontiers-fisherwomen-fiji"}]', '["animals"]', 'lairo | a large edible land crab found in coastal fiji. | | | coastal animal | land crab', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('9010c0a53b21729d', 'standard-fijian', 'word', 'ura', 'ura', 'noun', 'A prawn, particularly a freshwater prawn in Fiji.', '', '', '', '', '{"learnerComment":"Ura is a broader prawn name; ura dina is recorded for the native freshwater prawn Macrobrachium lar. Do not confuse a prawn with urau, a spiny lobster.","searchKeywords":["freshwater prawn","river prawn"],"furtherLink":{"label":"Explore ura in FAO, Fiji aquaculture station feasibility study","href":"https://www.fao.org/4/AC891E/AC891E03.htm"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"fao-fiji-prawn"}]', '["sea-life"]', 'ura | a prawn, particularly a freshwater prawn in fiji. | | | freshwater prawn | river prawn', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('f7c53a67aef2be0b', 'standard-fijian', 'word', 'uga vule', 'uga-vule', 'noun', 'The coconut crab, a large land-dwelling crustacean.', '', '', '', '', '{"learnerComment":"Ugavule is related to hermit crabs and spends most of its adult life on land. It differs from lairo, another land crab, in size and biology.","scientificName":"Birgus latro","searchKeywords":["coastal animal","land crab"],"furtherLink":{"label":"Explore uga vule in University of the South Pacific, Coconut crab report","href":"https://www.usp.ac.fj/institute-of-marine-resources/wp-content/uploads/sites/138/2021/08/Coconut-Crab-Report-.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"usp-coconut-crab"}]', '["animals"]', 'uga vule | the coconut crab, a large land-dwelling crustacean. | | | coastal animal | land crab', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('2d151b1333fba11c', 'standard-fijian', 'word', 'urau', 'urau', 'noun', 'A spiny lobster of Fiji''s reefs and coastal waters.', '', '', '', '', '{"learnerComment":"Urau is the spiny lobster, while vavaba names a slipper lobster with a flatter body. The broad name urau covers more than one species.","scientificName":"Panulirus spp.","searchKeywords":["spiny lobster","rock lobster"],"furtherLink":{"label":"Explore urau in Frontiers in Marine Science, marine resources in Qoma","href":"https://www.frontiersin.org/journals/marine-science/articles/10.3389/fmars.2022.993103/full"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"frontiers-qoma-marine"}]', '["sea-life"]', 'urau | a spiny lobster of fiji''s reefs and coastal waters. | | | spiny lobster | rock lobster', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('38fe55220be01012', 'standard-fijian', 'word', 'visako', 'visako', 'noun', 'Mangrove heron, a small shore bird.', '', '', '', '', '{"learnerComment":"Visako appears in a Fiji mangrove bird checklist beside its English name. It is a bird of the mangrove setting, not the reef heron belo.","scientificName":"Butorides striatus","searchKeywords":["mangrove bird","heron"],"furtherLink":{"label":"Explore visako in Pacific Science, Nasoata mangrove island fauna","href":"https://panorama.solutions/sites/default/files/2005_Thaman__R._et_al._Nasaota_Mangrove_Island__the_PABITRA_Coastal_Study_Site_for_Viti_Levu__Fiji_Islands.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"pacific-science-nasoata"}]', '["animals"]', 'visako | mangrove heron, a small shore bird. | | | mangrove bird | heron', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('9578a0be422ba12a', 'standard-fijian', 'word', 'dairo', 'dairo', 'noun', 'Sandfish, an edible sea cucumber.', '', '', '', '', '{"learnerComment":"Despite the English name, dairo is a sea cucumber, not a finfish. It lives on soft seabeds and is distinct from the many other sea cucumbers named in Fiji.","scientificName":"Holothuria scabra","searchKeywords":["sea cucumber","sandfish","coastal seafood"],"furtherLink":{"label":"Explore dairo in WCS Fiji, Fiji''s sea cucumber fishery","href":"https://fiji.wcs.org/Portals/82/reports/WCS%20Sea%20cucumber%20report%20260217.pdf?ver=2017-02-27-213114-827"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":""}}', '[{"sourceId":"wcs-sea-cucumber-fiji"}]', '["sea-life"]', 'dairo | sandfish, an edible sea cucumber. | | | sea cucumber | sandfish | coastal seafood', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
